USE [AgenciaEH];
GO
SET ANSI_NULLS ON; SET QUOTED_IDENTIFIER ON;
GO
IF OBJECT_ID('dbo.Users','U') IS NULL CREATE TABLE dbo.Users(
 Id uniqueidentifier NOT NULL CONSTRAINT PK_Users PRIMARY KEY, Email nvarchar(190) NOT NULL, FullName nvarchar(100) NOT NULL, Phone nvarchar(25) NULL, PasswordHash nvarchar(100) NOT NULL, Role varchar(20) NOT NULL, IsActive bit NOT NULL CONSTRAINT DF_Users_IsActive DEFAULT(1), RefreshTokenHash nvarchar(64) NULL, EmailVerificationTokenHash nvarchar(64) NULL, EmailVerificationExpiresAt datetime2(0) NULL, EmailVerifiedAt datetime2(0) NULL, PasswordResetTokenHash nvarchar(64) NULL, PasswordResetExpiresAt datetime2(0) NULL, CreatedAt datetime2(0) NOT NULL CONSTRAINT DF_Users_CreatedAt DEFAULT SYSUTCDATETIME(), UpdatedAt datetime2(0) NOT NULL CONSTRAINT DF_Users_UpdatedAt DEFAULT SYSUTCDATETIME(), CONSTRAINT UQ_Users_Email UNIQUE(Email), CONSTRAINT CK_Users_Role CHECK(Role IN('BUYER','AGENT','AGENCY','ADMIN')));
GO
IF OBJECT_ID('dbo.AgencyProfiles','U') IS NULL CREATE TABLE dbo.AgencyProfiles(Id uniqueidentifier NOT NULL CONSTRAINT PK_AgencyProfiles PRIMARY KEY, UserId uniqueidentifier NOT NULL, Name nvarchar(140) NOT NULL, Slug nvarchar(180) NOT NULL, Description nvarchar(1000) NULL, Phone nvarchar(25) NULL, CONSTRAINT UQ_AgencyProfiles_User UNIQUE(UserId), CONSTRAINT UQ_AgencyProfiles_Slug UNIQUE(Slug), CONSTRAINT FK_AgencyProfiles_Users FOREIGN KEY(UserId) REFERENCES dbo.Users(Id) ON DELETE CASCADE);
GO
IF OBJECT_ID('dbo.AgentProfiles','U') IS NULL CREATE TABLE dbo.AgentProfiles(Id uniqueidentifier NOT NULL CONSTRAINT PK_AgentProfiles PRIMARY KEY, UserId uniqueidentifier NOT NULL, AgencyId uniqueidentifier NULL, Bio nvarchar(1000) NULL, Phone nvarchar(25) NULL, CONSTRAINT UQ_AgentProfiles_User UNIQUE(UserId), CONSTRAINT FK_AgentProfiles_Users FOREIGN KEY(UserId) REFERENCES dbo.Users(Id) ON DELETE CASCADE, CONSTRAINT FK_AgentProfiles_Agencies FOREIGN KEY(AgencyId) REFERENCES dbo.AgencyProfiles(Id));
GO
IF OBJECT_ID('dbo.Properties','U') IS NULL CREATE TABLE dbo.Properties(Id uniqueidentifier NOT NULL CONSTRAINT PK_Properties PRIMARY KEY, Slug nvarchar(100) NOT NULL, Title nvarchar(180) NOT NULL, Description nvarchar(max) NOT NULL, Operation varchar(10) NOT NULL, Status varchar(20) NOT NULL CONSTRAINT DF_Properties_Status DEFAULT('DRAFT'), Price decimal(12,2) NOT NULL, Currency char(3) NOT NULL CONSTRAINT DF_Properties_Currency DEFAULT('MXN'), Municipality nvarchar(100) NOT NULL, Neighborhood nvarchar(120) NULL, PropertyType nvarchar(80) NOT NULL, Bedrooms int NULL, Bathrooms int NULL, LandArea decimal(12,2) NULL, BuiltArea decimal(12,2) NULL, OwnerId uniqueidentifier NOT NULL, CreatedAt datetime2(0) NOT NULL CONSTRAINT DF_Properties_CreatedAt DEFAULT SYSUTCDATETIME(), UpdatedAt datetime2(0) NOT NULL CONSTRAINT DF_Properties_UpdatedAt DEFAULT SYSUTCDATETIME(), CONSTRAINT UQ_Properties_Slug UNIQUE(Slug), CONSTRAINT FK_Properties_Users FOREIGN KEY(OwnerId) REFERENCES dbo.Users(Id), CONSTRAINT CK_Properties_Operation CHECK(Operation IN('RENT','SALE')), CONSTRAINT CK_Properties_Status CHECK(Status IN('DRAFT','REVIEW','PUBLISHED','RENTED','SOLD','REJECTED')), CONSTRAINT CK_Properties_Price CHECK(Price>0));
GO
IF OBJECT_ID('dbo.PropertyImages','U') IS NULL CREATE TABLE dbo.PropertyImages(Id uniqueidentifier NOT NULL CONSTRAINT PK_PropertyImages PRIMARY KEY, PropertyId uniqueidentifier NOT NULL, Url nvarchar(2048) NOT NULL, Alt nvarchar(250) NULL, Position int NOT NULL CONSTRAINT DF_PropertyImages_Position DEFAULT(0), CONSTRAINT FK_PropertyImages_Properties FOREIGN KEY(PropertyId) REFERENCES dbo.Properties(Id) ON DELETE CASCADE);
GO
IF OBJECT_ID('dbo.Leads','U') IS NULL CREATE TABLE dbo.Leads(Id uniqueidentifier NOT NULL CONSTRAINT PK_Leads PRIMARY KEY, PropertyId uniqueidentifier NULL, Name nvarchar(120) NOT NULL, Email nvarchar(190) NOT NULL, Phone nvarchar(25) NULL, Message nvarchar(2000) NULL, Status varchar(24) NOT NULL CONSTRAINT DF_Leads_Status DEFAULT('NEW'), AssignedToId uniqueidentifier NULL, CreatedAt datetime2(0) NOT NULL CONSTRAINT DF_Leads_CreatedAt DEFAULT SYSUTCDATETIME(), CONSTRAINT FK_Leads_Properties FOREIGN KEY(PropertyId) REFERENCES dbo.Properties(Id), CONSTRAINT FK_Leads_AssignedTo FOREIGN KEY(AssignedToId) REFERENCES dbo.Users(Id), CONSTRAINT CK_Leads_Status CHECK(Status IN('NEW','CONTACTED','VISIT_SCHEDULED','CLOSED','LOST')));
GO
IF OBJECT_ID('dbo.Favorites','U') IS NULL CREATE TABLE dbo.Favorites(Id uniqueidentifier NOT NULL CONSTRAINT PK_Favorites PRIMARY KEY, UserId uniqueidentifier NOT NULL, PropertyId uniqueidentifier NOT NULL, CreatedAt datetime2(0) NOT NULL CONSTRAINT DF_Favorites_CreatedAt DEFAULT SYSUTCDATETIME(), CONSTRAINT UQ_Favorites_User_Property UNIQUE(UserId,PropertyId), CONSTRAINT FK_Favorites_Users FOREIGN KEY(UserId) REFERENCES dbo.Users(Id) ON DELETE CASCADE, CONSTRAINT FK_Favorites_Properties FOREIGN KEY(PropertyId) REFERENCES dbo.Properties(Id) ON DELETE CASCADE);
GO
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Properties_PublicSearch' AND object_id=OBJECT_ID('dbo.Properties')) CREATE INDEX IX_Properties_PublicSearch ON dbo.Properties(Status,Operation,Municipality,Price) INCLUDE(Title,Slug,PropertyType,Bedrooms,Bathrooms,CreatedAt);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Properties_Owner' AND object_id=OBJECT_ID('dbo.Properties')) CREATE INDEX IX_Properties_Owner ON dbo.Properties(OwnerId,UpdatedAt DESC);
IF NOT EXISTS(SELECT 1 FROM sys.indexes WHERE name='IX_Leads_Assigned_Status' AND object_id=OBJECT_ID('dbo.Leads')) CREATE INDEX IX_Leads_Assigned_Status ON dbo.Leads(AssignedToId,Status,CreatedAt DESC);
GO
